// SQL of registration and login. Registration runs as antre_app in the context of the tenant id
// generated by the service (spec section 6.1 point 6); login uses the SECURITY DEFINER function
// app_auth_find_user, the only way to find an account before the tenant is known.
import type { RegisterRequest, UserRole } from '@antre/shared-types';
import type pg from 'pg';

import { USER_COLUMNS, type UserRow } from '../users/queries.js';

export interface RegisteredTenant {
  tenant: { id: string; name: string; slug: string };
  location: { id: string; code: string; name: string };
  owner: UserRow;
}

/** Inserts tenant, owner, first location, and its FREE subscription. Call inside withTransaction. */
export async function insertTenantWithOwner(
  client: pg.PoolClient,
  tenantId: string,
  request: RegisterRequest,
  passwordHash: string,
): Promise<RegisteredTenant> {
  const { tenant, location, owner } = request;

  await client.query(
    `INSERT INTO tenants (id, name, slug, business_type, admin_wa_phone)
     VALUES ($1, $2, $3, $4, $5)`,
    [tenantId, tenant.name, tenant.slug, tenant.business_type, tenant.admin_wa_phone],
  );

  const ownerResult = await client.query<UserRow>(
    `INSERT INTO users (tenant_id, email, password_hash, role)
     VALUES ($1, $2, $3, 'OWNER')
     RETURNING ${USER_COLUMNS}`,
    [tenantId, owner.email, passwordHash],
  );

  const locationResult = await client.query<{ id: string; code: string; name: string }>(
    `INSERT INTO locations (tenant_id, code, name, address, timezone)
     VALUES ($1, $2, $3, $4, $5)
     RETURNING id, code, name`,
    [tenantId, location.code, location.name, location.address ?? null, location.timezone],
  );
  const insertedLocation = locationResult.rows[0]!;

  await client.query('INSERT INTO subscriptions (tenant_id, location_id) VALUES ($1, $2)', [
    tenantId,
    insertedLocation.id,
  ]);

  return {
    tenant: { id: tenantId, name: tenant.name, slug: tenant.slug },
    location: insertedLocation,
    owner: ownerResult.rows[0]!,
  };
}

export interface LoginUserRow {
  id: string;
  tenant_id: string | null;
  password_hash: string;
  role: UserRole;
}

export async function findUserForLogin(pool: pg.Pool, email: string): Promise<LoginUserRow | null> {
  const result = await pool.query<LoginUserRow>(
    'SELECT id, tenant_id, password_hash, role FROM app_auth_find_user($1)',
    [email],
  );
  return result.rows[0] ?? null;
}
